for slug, obj in files.items():
    txt = json.dumps(obj, ensure_ascii=False, indent=1)
    # проверка: никаких прямых двойных кавычек внутри значений
    def walk(o):
        if isinstance(o, str):
            assert '"' not in o, (slug, o[:80])
        elif isinstance(o, dict):
            for k, v in o.items(): walk(k); walk(v)
        elif isinstance(o, list):
            for v in o: walk(v)
    walk(obj)
    p = os.path.join(D, slug + '.json')
    open(p, 'w', encoding='utf-8').write(txt)
    json.load(open(p, encoding='utf-8'))
    print('ok', slug, len(txt))
